 "content": "def transform(grid):
    n = len(grid)
    # Separator lattice divides the image into equal square panels.
    sep = next((v for v in range(10) if all(x == v for x in grid[n // 2]) and v != 0), None)
    if sep is None:
        raise ValueError('separator row not found')
    lines = [i for i, row in enumerate(grid) if all(x == sep for x in row)]
    cols = [j for j in range(len(grid[0])) if all(grid[i][j] == sep for i in range(n))]
    h = lines[0]
    w = cols[0]
    nr = len(lines) + 1
    nc = len(cols) + 1
    # The pattern is the non-background, non-separator object in an otherwise blank panel.
    bg = 0
    panels = []
    for r in range(nr):
        for c in range(nc):
            r0, c0 = r * (h + 1), c * (w + 1)
            panels.append((r, c, [[grid[r0+i][c0+j] for j in range(w)] for i in range(h)]))
    pattern_panel = None
    for r, c, p in panels:
        colors = {x for row in p for x in row if x not in (bg, sep)}
        if len(colors) > 1 or (colors and sum(x != bg for row in p for x in row) != 4):
            pattern_panel = p
            break
    if pattern_panel is None:
        # Select the panel containing the largest non-2x2 object as the template.
        pattern_panel = max((p for _, _, p in panels), key=lambda p: sum(x not in (bg, sep) for row in p for x in row))
    colors = [x for row in pattern_panel for x in row if x not in (bg, sep)]
    if not colors:
        return grid
    template_color = max(set(colors), key=colors.count)
    mask = [[x == template_color for x in row] for row in pattern_panel]
    # Row identity is supplied by the colored 2x2 key in the first panel of each band.
    row_colors = []
    for r in range(nr):
        p = panels[r*nc][2]
        vals = [x for row in p for x in row if x not in (bg, sep)]
        row_colors.append(vals[0] if vals else template_color)
    out = [[bg for _ in row] for row in grid]
    for i in range(n):
        for j in range(len(grid[0])):
            if grid[i][j] == sep:
                out[i][j] = sep
    for r in range(nr):
        for c in range(nc):
            r0, c0 = r * (h + 1), c * (w + 1)
            color = row_colors[r]
            for i in range(h):
                for j in range(w):
                    if mask[i][j]:
                        out[r0+i][c0+j] = color
    return out
